cd /work/workspace && python3 - <<'PY'
import json, re, os
cits = json.load(open('deliverable/citations.json'))
if isinstance(cits, dict):
    for k,v in cits.items():
        if isinstance(v, list):
            cits = v; break
idx = open('library/INDEX.md').read()
rows = [ [c.strip() for c in r.strip().split('|')] for r in re.findall(r'^\|(.+)\|\s*$', idx, re.M) ]
rows = [r for r in rows if len(r)>=5 and r[0] not in ('File','')]
status = {}
for r in rows:
    f = r[0].strip('`* ')
    status[f] = r[4]
print("INDEX entries:", len(status))
memo_bank = [f for f in status if f.startswith('memo_bank') or 'memo_bank' in f]
print("memo bank rows:", memo_bank)

required = None
problems = []
for i,c in enumerate(cits):
    keys = set(c.keys())
    if i==0: required = keys
    if keys != required:
        problems.append(f"entry {i} key mismatch: {sorted(keys)} vs {sorted(required)}")
    lf = c.get('library_file') or c.get('file')
    if lf not in status:
        problems.append(f"entry {i} library_file NOT in INDEX: {lf}")
    elif lf.startswith('memo_bank') or 'memo_bank' in lf:
        problems.append(f"entry {i} cites memo bank: {lf}")
    else:
        st_idx = status[lf]
        st_ch = c.get('status_checked')
        if st_ch != st_idx:
            problems.append(f"entry {i} status mismatch: {lf} json={st_ch!r} index={st_idx!r}")
    # file exists?
    if lf and not os.path.exists(os.path.join('library', lf)):
        problems.append(f"entry {i} file missing on disk: {lf}")
print("PROBLEMS:", len(problems))
for p in problems: print(" -", p)
# show mapping
print()
for c in cits:
    print(f"{c.get('authority','?')[:52]:54} {c.get('library_file')} [{c.get('status_checked')}]")
