import json, re, os
raw = json.load(open('deliverable/citations.json'))
cits = raw if isinstance(raw, list) else next(v for v in raw.values() if isinstance(v, list))
print("top-level type:", type(raw).__name__, "keys:", list(raw.keys()) if isinstance(raw,dict) else None)
print("entry0 keys:", list(cits[0].keys()))
idx = open('library/INDEX.md').read()
rows = [[c.strip() for c in r.strip().split('|')] for r in re.findall(r'^\|(.+)\|\s*$', idx, re.M)]
rows = [r for r in rows if len(r)>=5 and r[0] not in ('File','') and not set(r[0])<=set('-: ')]
status = {r[0].strip('`* '): r[4] for r in rows}
def norm(p):
    p = p.strip()
    for pre in ('library/','./library/','workspace/library/'):
        if p.startswith(pre): p = p[len(pre):]
    return p
problems=[]
keysets=set()
for i,c in enumerate(cits):
    keysets.add(tuple(sorted(c.keys())))
    lf = norm(c.get('library_file',''))
    if lf not in status: problems.append(f"{i}: library_file not in INDEX -> {c.get('library_file')}")
    elif 'memo_bank' in lf: problems.append(f"{i}: memo bank cited -> {lf}")
    else:
        if c.get('status_checked') != status[lf]:
            problems.append(f"{i}: status mismatch {lf}: json={c.get('status_checked')!r} index={status[lf]!r}")
        if not os.path.exists('library/'+lf): problems.append(f"{i}: missing on disk {lf}")
print("distinct key sets:", keysets)
print("PROBLEMS:", problems)
print("citable INDEX rows (excl memo bank):", sorted(set(status)-{f for f in status if 'memo_bank' in f}))
used = {norm(c['library_file']) for c in cits}
print("uncited but citable:", sorted(set(status)-{f for f in status if 'memo_bank' in f} - used))
